#!/usr/bin/env python3
import sys, json, re
from dataclasses import dataclass

VERSION = "18.0.0"
PROG = "executable"
MASK64 = (1 << 64) - 1

# ---- Keccak-256 (Ethereum padding, not NIST SHA3 padding) ----
_KECCAK_RC = [
    0x0000000000000001, 0x0000000000008082, 0x800000000000808A,
    0x8000000080008000, 0x000000000000808B, 0x0000000080000001,
    0x8000000080008081, 0x8000000000008009, 0x000000000000008A,
    0x0000000000000088, 0x0000000080008009, 0x000000008000000A,
    0x000000008000808B, 0x800000000000008B, 0x8000000000008089,
    0x8000000000008003, 0x8000000000008002, 0x8000000000000080,
    0x000000000000800A, 0x800000008000000A, 0x8000000080008081,
    0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
]
_KECCAK_ROTC = [1, 3, 6, 10, 15, 21, 28, 36, 45, 55, 2, 14, 27, 41, 56, 8, 25, 43, 62, 18, 39, 61, 20, 44]
_KECCAK_PILN = [10, 7, 11, 17, 18, 3, 5, 16, 8, 21, 24, 4, 15, 23, 19, 13, 12, 2, 20, 14, 22, 9, 6, 1]

def _rol(x, n):
    return ((x << n) | (x >> (64 - n))) & MASK64

def _keccak_f(st):
    for rc in _KECCAK_RC:
        bc = [0] * 5
        for i in range(5):
            bc[i] = st[i] ^ st[i+5] ^ st[i+10] ^ st[i+15] ^ st[i+20]
        for i in range(5):
            t = bc[(i + 4) % 5] ^ _rol(bc[(i + 1) % 5], 1)
            for j in range(0, 25, 5):
                st[j + i] ^= t
        t = st[1]
        for i in range(24):
            j = _KECCAK_PILN[i]
            bc0 = st[j]
            st[j] = _rol(t, _KECCAK_ROTC[i])
            t = bc0
        for j in range(0, 25, 5):
            row = st[j:j+5]
            for i in range(5):
                st[j+i] = row[i] ^ ((~row[(i+1) % 5]) & row[(i+2) % 5])
                st[j+i] &= MASK64
        st[0] ^= rc

def keccak256(data: bytes) -> bytes:
    rate = 136
    st = [0] * 25
    off = 0
    while off + rate <= len(data):
        block = data[off:off+rate]
        for i in range(rate // 8):
            st[i] ^= int.from_bytes(block[8*i:8*i+8], 'little')
        _keccak_f(st)
        off += rate
    block = bytearray(data[off:])
    block.append(0x01)
    while len(block) < rate:
        block.append(0)
    block[-1] ^= 0x80
    for i in range(rate // 8):
        st[i] ^= int.from_bytes(block[8*i:8*i+8], 'little')
    _keccak_f(st)
    out = bytearray()
    while len(out) < 32:
        for i in range(rate // 8):
            out += st[i].to_bytes(8, 'little')
        if len(out) >= 32:
            break
        _keccak_f(st)
    return bytes(out[:32])

# ---- ABI types ----
@dataclass(frozen=True)
class ABIType:
    kind: str
    bits: int = None
    size: int = None
    elem: object = None

    def canonical(self):
        if self.kind == 'uint': return f"uint{self.bits or 256}"
        if self.kind == 'int': return f"int{self.bits or 256}"
        if self.kind == 'bytes_fixed': return f"bytes{self.size}"
        if self.kind == 'array': return self.elem.canonical() + '[' + ('' if self.size is None else str(self.size)) + ']'
        return self.kind

    def dynamic(self):
        if self.kind in ('string', 'bytes'):
            return True
        if self.kind == 'array':
            return self.size is None or self.elem.dynamic()
        return False

    def static_words(self):
        if self.dynamic():
            return 1
        if self.kind == 'array':
            return self.size * self.elem.static_words()
        return 1

class ABIError(Exception):
    pass

class HexParseError(ABIError):
    def __init__(self, msg, caused=False):
        super().__init__(msg)
        self.caused = caused

def parse_type(s: str) -> ABIType:
    orig = s
    suffixes = []
    while s.endswith(']'):
        lb = s.rfind('[')
        if lb < 0:
            raise ABIError('Invalid data')
        inside = s[lb+1:-1]
        if inside == '':
            suffixes.append(None)
        elif inside.isdigit():
            suffixes.append(int(inside))
        else:
            raise ABIError('Invalid data')
        s = s[:lb]
    if s == 'bool': t = ABIType('bool')
    elif s == 'address': t = ABIType('address')
    elif s == 'string': t = ABIType('string')
    elif s == 'bytes': t = ABIType('bytes')
    elif s == 'uint': t = ABIType('uint', bits=256)
    elif s == 'int': t = ABIType('int', bits=256)
    elif re.fullmatch(r'uint[0-9]+', s): t = ABIType('uint', bits=int(s[4:]))
    elif re.fullmatch(r'int[0-9]+', s): t = ABIType('int', bits=int(s[3:]))
    elif re.fullmatch(r'bytes[0-9]+', s):
        n = int(s[5:])
        if n < 1 or n > 32: raise ABIError('Invalid data')
        t = ABIType('bytes_fixed', size=n)
    else:
        raise ABIError('Invalid data')
    for dim in reversed(suffixes):
        t = ABIType('array', size=dim, elem=t)
    return t

def strip_0x(s):
    return s[2:] if s.startswith(('0x', '0X')) else s

def hex_to_bytes(s: str, allow_prefix=True) -> bytes:
    if allow_prefix:
        s2 = strip_0x(s)
    else:
        s2 = s
    if len(s2) % 2:
        raise HexParseError('Odd number of digits', caused=True)
    for i, ch in enumerate(s2):
        if ch not in '0123456789abcdefABCDEF':
            # position mirrors the post-optional-prefix string for params; decode data disallows prefix.
            raise HexParseError(f"Invalid character '{ch}' at position {i}", caused=True)
    try:
        return bytes.fromhex(s2)
    except ValueError:
        raise HexParseError('Invalid data')

def word(n: int) -> bytes:
    return (n % (1 << 256)).to_bytes(32, 'big')

def pad_right(b: bytes) -> bytes:
    return b + b'\x00' * ((32 - (len(b) % 32)) % 32)

def split_array_items(s: str):
    if not (len(s) >= 2 and s[0] == '[' and s[-1] == ']'):
        raise ABIError('Invalid data')
    inner = s[1:-1]
    if inner == '':
        return []
    res, cur, depth = [], [], 0
    for ch in inner:
        if ch == '[':
            depth += 1; cur.append(ch)
        elif ch == ']':
            depth -= 1; cur.append(ch)
            if depth < 0: raise ABIError('Invalid data')
        elif ch == ',' and depth == 0:
            res.append(''.join(cur).strip()); cur=[]
        else:
            cur.append(ch)
    if depth != 0: raise ABIError('Invalid data')
    res.append(''.join(cur).strip())
    return res

def parse_token(t: ABIType, s: str, lenient=False):
    if t.kind == 'array':
        items = split_array_items(s)
        if t.size is not None and len(items) != t.size:
            raise ABIError('Invalid data')
        return [parse_token(t.elem, it, lenient) for it in items]
    if t.kind == 'bool':
        sl = s.lower()
        if sl in ('true', '1'): return True
        if sl in ('false', '0'): return False
        raise ABIError('Invalid data')
    if t.kind == 'address':
        b = hex_to_bytes(s, allow_prefix=True)
        if len(b) != 20: raise ABIError('Invalid data')
        return b
    if t.kind == 'bytes_fixed':
        b = hex_to_bytes(s, allow_prefix=True)
        if len(b) != t.size: raise ABIError('Invalid data')
        return b
    if t.kind == 'bytes':
        return hex_to_bytes(s, allow_prefix=True)
    if t.kind == 'string':
        return s
    if t.kind in ('uint', 'int'):
        if lenient:
            try:
                n = int(s, 10)
            except ValueError:
                raise ABIError('Invalid data')
            return n % (1 << 256)
        b = hex_to_bytes(s, allow_prefix=True)
        if len(b) != 32: raise ABIError('Invalid data')
        return int.from_bytes(b, 'big')
    raise ABIError('Invalid data')

# ---- encoding ----
def encode_static(t: ABIType, v) -> bytes:
    if t.kind in ('uint', 'int'):
        return word(int(v))
    if t.kind == 'bool':
        return word(1 if v else 0)
    if t.kind == 'address':
        return b'\x00' * 12 + bytes(v)
    if t.kind == 'bytes_fixed':
        return bytes(v) + b'\x00' * (32 - len(v))
    if t.kind == 'array' and not t.dynamic():
        out = bytearray()
        for x in v:
            out += encode_static(t.elem, x)
        return bytes(out)
    raise ABIError('Invalid data')

def encode_dynamic(t: ABIType, v) -> bytes:
    if t.kind == 'string':
        b = v.encode('utf-8')
        return word(len(b)) + pad_right(b)
    if t.kind == 'bytes':
        b = bytes(v)
        return word(len(b)) + pad_right(b)
    if t.kind == 'array':
        if t.size is None:
            return word(len(v)) + encode_sequence([t.elem] * len(v), v)
        # fixed array whose element is dynamic
        return encode_sequence([t.elem] * len(v), v)
    raise ABIError('Invalid data')

def encode_sequence(types, values) -> bytes:
    head_size = 32 * sum(1 if t.dynamic() else t.static_words() for t in types)
    head = bytearray(); tail = bytearray()
    for t, v in zip(types, values):
        if t.dynamic():
            head += word(head_size + len(tail))
            tail += encode_dynamic(t, v)
        else:
            head += encode_static(t, v)
    return bytes(head + tail)

# ---- decoding ----
def read_word(data: bytes, pos: int) -> int:
    if pos < 0 or pos + 32 > len(data):
        raise ABIError('Invalid data')
    return int.from_bytes(data[pos:pos+32], 'big')

def decode_at(t: ABIType, data: bytes, pos: int):
    if t.kind in ('uint', 'int'):
        return read_word(data, pos)
    if t.kind == 'bool':
        return read_word(data, pos) != 0
    if t.kind == 'address':
        return data[pos+12:pos+32] if pos + 32 <= len(data) else (_raise_invalid())
    if t.kind == 'bytes_fixed':
        if pos + 32 > len(data): raise ABIError('Invalid data')
        return data[pos:pos+t.size]
    if t.kind == 'string':
        n = read_word(data, pos)
        start = pos + 32
        if start + n > len(data): raise ABIError('Invalid data')
        return data[start:start+n].decode('utf-8', errors='replace')
    if t.kind == 'bytes':
        n = read_word(data, pos)
        start = pos + 32
        if start + n > len(data): raise ABIError('Invalid data')
        return data[start:start+n]
    if t.kind == 'array':
        if t.size is None:
            n = read_word(data, pos)
            base = pos + 32
        else:
            n = t.size
            base = pos
        vals = []
        if t.elem.dynamic():
            for i in range(n):
                off = read_word(data, base + 32*i)
                vals.append(decode_at(t.elem, data, base + off))
        else:
            p = base
            step = 32 * t.elem.static_words()
            for i in range(n):
                vals.append(decode_at(t.elem, data, p))
                p += step
        return vals
    raise ABIError('Invalid data')

def _raise_invalid():
    raise ABIError('Invalid data')

def decode_sequence(types, data: bytes):
    vals = []
    pos = 0
    for t in types:
        if t.dynamic():
            off = read_word(data, pos)
            vals.append(decode_at(t, data, off))
            pos += 32
        else:
            vals.append(decode_at(t, data, pos))
            pos += 32 * t.static_words()
    return vals

# ---- display ----
def display_value(t: ABIType, v):
    if t.kind in ('uint', 'int'):
        return format(int(v), 'x')
    if t.kind == 'bool':
        return 'true' if v else 'false'
    if t.kind == 'address':
        return bytes(v).hex()
    if t.kind in ('bytes', 'bytes_fixed'):
        return bytes(v).hex()
    if t.kind == 'string':
        return v
    if t.kind == 'array':
        return '[' + ','.join(display_value(t.elem, x) for x in v) + ']'
    return str(v)

# ---- ABI JSON lookup ----
def load_abi(path):
    try:
        with open(path, 'r') as f:
            return json.load(f)
    except Exception as e:
        raise ABIError(str(e))

def item_inputs(item):
    return [parse_type(x.get('type', '')) for x in item.get('inputs', [])]

def item_outputs(item):
    return [parse_type(x.get('type', '')) for x in item.get('outputs', [])]

def canonical_signature(item, include_outputs=False):
    ins = ','.join(parse_type(x.get('type','')).canonical() for x in item.get('inputs', []))
    base = f"{item.get('name','')}({ins})"
    if include_outputs and item.get('outputs'):
        outs = ','.join(parse_type(x.get('type','')).canonical() for x in item.get('outputs', []))
        base += f":({outs})"
    return base

def lookup_function(abi, name):
    funcs = [x for x in abi if x.get('type') == 'function']
    if '(' in name or ':' in name:
        for f in funcs:
            if name == canonical_signature(f, include_outputs=True):
                return f
        raise ABIError(f"invalid function signature `{name}`")
    found = [f for f in funcs if f.get('name') == name]
    if not found:
        raise ABIError(f"Invalid name: {name}")
    if len(found) > 1:
        raise ABIError(f"More than one function found for name `{name}`, try providing the full signature")
    return found[0]

def lookup_event(abi, name):
    evs = [x for x in abi if x.get('type') == 'event']
    if '(' in name:
        for e in evs:
            if name == canonical_signature(e, include_outputs=False):
                return e
        raise ABIError(f"invalid event signature `{name}`")
    found = [e for e in evs if e.get('name') == name]
    if not found:
        raise ABIError(f"Invalid name: {name}")
    if len(found) > 1:
        raise ABIError(f"More than one event found for name `{name}`, try providing the full signature")
    return found[0]

def function_selector(item):
    return keccak256(canonical_signature(item, include_outputs=False).encode())[:4]

def event_topic(item):
    return keccak256(canonical_signature(item, include_outputs=False).encode())

# ---- command-line helpers ----
def print_main_help(to_stderr=False):
    s = f"ethabi-cli {VERSION}\nEthereum ABI coder\n\nUSAGE:\n    {PROG} <SUBCOMMAND>\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nSUBCOMMANDS:\n    decode    Decode ABI call result\n    encode    Encode ABI call\n    help      Prints this message or the help of the given subcommand(s)\n"
    (sys.stderr if to_stderr else sys.stdout).write(s)

def print_encode_help(to_stderr=False):
    s = f"{PROG}-encode {VERSION}\nEncode ABI call\n\nUSAGE:\n    {PROG} encode <SUBCOMMAND>\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nSUBCOMMANDS:\n    function    Load function from JSON ABI file\n    help        Prints this message or the help of the given subcommand(s)\n    params      Specify types of input params inline\n"
    (sys.stderr if to_stderr else sys.stdout).write(s)

def print_decode_help(to_stderr=False):
    s = f"{PROG}-decode {VERSION}\nDecode ABI call result\n\nUSAGE:\n    {PROG} decode <SUBCOMMAND>\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nSUBCOMMANDS:\n    function    Load function from JSON ABI file\n    help        Prints this message or the help of the given subcommand(s)\n    log         Decode event log\n    params      Specify types of input params inline\n"
    (sys.stderr if to_stderr else sys.stdout).write(s)

def print_encode_params_help():
    sys.stdout.write(f"{PROG}-encode-params {VERSION}\nSpecify types of input params inline\n\nUSAGE:\n    {PROG} encode params [FLAGS] [OPTIONS]\n\nFLAGS:\n    -h, --help       Prints help information\n    -l, --lenient    Allow short representation of input params (numbers are in decimal form)\n    -V, --version    Prints version information\n\nOPTIONS:\n    -v <type-or-param> <type-or-param>        Pairs of types directly followed by params in the form:\n")

def print_encode_function_help():
    sys.stdout.write(f"{PROG}-encode-function {VERSION}\nLoad function from JSON ABI file\n\nUSAGE:\n    {PROG} encode function [FLAGS] [OPTIONS] <abi-path> <function-name-or-signature>\n\nFLAGS:\n    -h, --help       Prints help information\n    -l, --lenient    Allow short representation of input params\n    -V, --version    Prints version information\n\nOPTIONS:\n    -p <params>...        \n\nARGS:\n    <abi-path>                      \n    <function-name-or-signature>    \n")

def print_decode_params_help():
    sys.stdout.write(f"{PROG}-decode-params {VERSION}\nSpecify types of input params inline\n\nUSAGE:\n    {PROG} decode params [OPTIONS] <data>\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nOPTIONS:\n    -t <type>...        \n\nARGS:\n    <data>    \n")

def print_decode_function_help():
    sys.stdout.write(f"{PROG}-decode-function {VERSION}\nLoad function from JSON ABI file\n\nUSAGE:\n    {PROG} decode function <abi-path> <function-name-or-signature> <data>\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nARGS:\n    <abi-path>                      \n    <function-name-or-signature>    \n    <data>                          \n")

def print_decode_log_help():
    sys.stdout.write(f"{PROG}-decode-log {VERSION}\nDecode event log\n\nUSAGE:\n    {PROG} decode log [OPTIONS] <abi-path> <event-name-or-signature> <data>\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nOPTIONS:\n    -l <topic>...        \n\nARGS:\n    <abi-path>                   \n    <event-name-or-signature>    \n    <data>                       \n")

def fail_error(e):
    msg = str(e)
    if isinstance(e, HexParseError):
        if e.caused:
            sys.stderr.write(f"Error: Hex parsing error: {msg}\n\nCaused by:\n    {msg}\n")
        else:
            sys.stderr.write(f"Error: {msg}\n")
    else:
        sys.stderr.write(f"Error: {msg}\n")
    return 1

def fail_clap(msg, usage):
    sys.stderr.write(f"error: {msg}\n\nUSAGE:\n    {usage}\n\nFor more information try --help\n")
    return 1

# ---- commands ----
def cmd_encode_params(argv):
    if '-h' in argv or '--help' in argv:
        print_encode_params_help(); return 0
    if '-V' in argv or '--version' in argv:
        print('ethabi-cli ' + VERSION); return 0
    lenient = False; pairs=[]; i=0
    try:
        while i < len(argv):
            a=argv[i]
            if a in ('-l','--lenient'):
                lenient=True; i+=1
            elif a == '-v':
                if i+2 >= len(argv):
                    return fail_clap("The argument '-v <type-or-param> <type-or-param>' requires 2 values, but 1 was provided", f"{PROG} encode params -v <type-or-param> <type-or-param>")
                pairs.append((argv[i+1], argv[i+2])); i+=3
            else:
                # clap would reject, but positional leftovers are harmless here only if none expected.
                i+=1
        types=[parse_type(t) for t,_ in pairs]
        vals=[parse_token(t,v,lenient) for t,(_,v) in zip(types,pairs)]
        sys.stdout.write(encode_sequence(types, vals).hex() + ('\n' if pairs else '\n'))
        return 0
    except ABIError as e:
        return fail_error(e)

def collect_p_args(rest):
    vals=[]; i=0; other=[]
    while i < len(rest):
        if rest[i] == '-p':
            i+=1
            while i < len(rest) and not rest[i].startswith('-'):
                vals.append(rest[i]); i+=1
        else:
            other.append(rest[i]); i+=1
    return vals, other

def cmd_encode_function(argv):
    if '-h' in argv or '--help' in argv:
        print_encode_function_help(); return 0
    if '-V' in argv or '--version' in argv:
        print('ethabi-cli ' + VERSION); return 0
    lenient=False; rest=[]; i=0
    while i < len(argv):
        if argv[i] in ('-l','--lenient'):
            lenient=True; i+=1
        else:
            rest.append(argv[i]); i+=1
    if len(rest) < 2:
        return fail_clap("The following required arguments were not provided:\n    <abi-path>\n    <function-name-or-signature>", f"{PROG} encode function <abi-path> <function-name-or-signature>")
    abi_path, fname = rest[0], rest[1]
    pvals, _ = collect_p_args(rest[2:])
    try:
        f = lookup_function(load_abi(abi_path), fname)
        types = item_inputs(f)
        vals = []
        for t, s in zip(types, pvals):
            vals.append(parse_token(t, s, lenient))
        if len(vals) < len(types):
            raise ABIError('Invalid data')
        out = function_selector(f) + encode_sequence(types, vals)
        print(out.hex())
        return 0
    except ABIError as e:
        return fail_error(e)

def cmd_decode_params(argv):
    if '-h' in argv or '--help' in argv:
        print_decode_params_help(); return 0
    if '-V' in argv or '--version' in argv:
        print('ethabi-cli ' + VERSION); return 0
    typestrs=[]; data_arg=None; i=0
    while i < len(argv):
        if argv[i] == '-t':
            i+=1
            if i >= len(argv):
                return fail_clap("The argument '-t <type>...' requires at least 1 value", f"{PROG} decode params -t <type>... <data>")
            # clap option is multiple; in observed usage each -t one value. Consume one.
            typestrs.append(argv[i]); i+=1
        else:
            data_arg=argv[i]; i+=1
    if data_arg is None:
        usage = f"{PROG} decode params <data>" + (" -t <type>..." if typestrs else " [OPTIONS] <data>")
        return fail_clap("The following required arguments were not provided:\n    <data>", usage)
    try:
        types=[parse_type(x) for x in typestrs]
        data=hex_to_bytes(data_arg, allow_prefix=False)
        vals=decode_sequence(types, data)
        for t,v in zip(types, vals):
            print(t.canonical(), display_value(t,v))
        return 0
    except ABIError as e:
        return fail_error(e)

def cmd_decode_function(argv):
    if '-h' in argv or '--help' in argv:
        print_decode_function_help(); return 0
    if '-V' in argv or '--version' in argv:
        print('ethabi-cli ' + VERSION); return 0
    if len(argv) < 3:
        return fail_clap("The following required arguments were not provided:\n    <abi-path>\n    <function-name-or-signature>\n    <data>", f"{PROG} decode function <abi-path> <function-name-or-signature> <data>")
    try:
        f=lookup_function(load_abi(argv[0]), argv[1])
        types=item_outputs(f)
        data=hex_to_bytes(argv[2], allow_prefix=False)
        vals=decode_sequence(types, data)
        for t,v in zip(types, vals):
            print(t.canonical(), display_value(t,v))
        return 0
    except ABIError as e:
        return fail_error(e)

def cmd_decode_log(argv):
    if '-h' in argv or '--help' in argv:
        print_decode_log_help(); return 0
    if '-V' in argv or '--version' in argv:
        print('ethabi-cli ' + VERSION); return 0
    topics=[]; rest=[]; i=0
    while i < len(argv):
        if argv[i] == '-l':
            i+=1
            if i >= len(argv):
                return fail_clap("The argument '-l <topic>...' requires at least 1 value", f"{PROG} decode log -l <topic>... <abi-path> <event-name-or-signature> <data>")
            topics.append(argv[i]); i+=1
        else:
            rest.append(argv[i]); i+=1
    if len(rest) < 3:
        return fail_clap("The following required arguments were not provided", f"{PROG} decode log [OPTIONS] <abi-path> <event-name-or-signature> <data>")
    try:
        e=lookup_event(load_abi(rest[0]), rest[1])
        data=hex_to_bytes(rest[2], allow_prefix=False)
        topic_bytes=[hex_to_bytes(x, allow_prefix=False) for x in topics]
        for tb in topic_bytes:
            if len(tb) != 32: raise ABIError('Invalid data')
        anonymous = bool(e.get('anonymous', False))
        if not anonymous:
            if not topic_bytes or topic_bytes[0] != event_topic(e):
                raise ABIError('Invalid data')
            topic_bytes = topic_bytes[1:]
        inputs=e.get('inputs', [])
        indexed=[]; non=[]
        for inp in inputs:
            (indexed if inp.get('indexed') else non).append(inp)
        if len(topic_bytes) < len(indexed):
            raise ABIError('Invalid data')
        ntypes=[parse_type(x.get('type','')) for x in non]
        nvals=decode_sequence(ntypes, data)
        ni=0; ti=0
        for inp in inputs:
            name=inp.get('name','')
            t=parse_type(inp.get('type',''))
            if inp.get('indexed'):
                tb=topic_bytes[ti]; ti+=1
                # Dynamic indexed values are represented by their hash topic.
                if t.dynamic():
                    val = tb
                    shown = tb.hex()
                else:
                    val = decode_at(t, tb, 0)
                    shown = display_value(t, val)
                print(name, shown)
            else:
                val=nvals[ni]; ni+=1
                print(name, display_value(t,val))
        return 0
    except ABIError as e:
        return fail_error(e)

def main(argv):
    if not argv:
        print_main_help(to_stderr=True); return 1
    if argv[0] in ('-h','--help','help'):
        print_main_help(); return 0
    if argv[0] in ('-V','--version'):
        print('ethabi-cli ' + VERSION); return 0
    if argv[0] == 'encode':
        if len(argv) == 1:
            print_encode_help(to_stderr=True); return 1
        if argv[1] in ('-h','--help','help'):
            print_encode_help(); return 0
        if argv[1] in ('-V','--version'):
            print('ethabi-cli ' + VERSION); return 0
        if argv[1] == 'params': return cmd_encode_params(argv[2:])
        if argv[1] == 'function': return cmd_encode_function(argv[2:])
        print_encode_help(to_stderr=True); return 1
    if argv[0] == 'decode':
        if len(argv) == 1:
            print_decode_help(to_stderr=True); return 1
        if argv[1] in ('-h','--help','help'):
            print_decode_help(); return 0
        if argv[1] in ('-V','--version'):
            print('ethabi-cli ' + VERSION); return 0
        if argv[1] == 'params': return cmd_decode_params(argv[2:])
        if argv[1] == 'function': return cmd_decode_function(argv[2:])
        if argv[1] == 'log': return cmd_decode_log(argv[2:])
        print_decode_help(to_stderr=True); return 1
    print_main_help(to_stderr=True); return 1

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
