            lenient=True; i+=1
        else:
            rest.append(argv[i]); i+=1
    if len(rest) < 2:
        return fail_clap("The following required arguments were not provided:\n    <abi-path>\n    <function-name-or-signature>", f"{PROG} encode function <abi-path> <function-name-or-signature>")
    abi_path, fname = rest[0], rest[1]
    pvals, _ = collect_p_args(rest[2:])
    try:
